module TopModule (
    input  in,
    input  state,
    output next_state,
    output out
);

    // State encoding: A=4'b0001, B=4'b0010, C=4'b0100, D=4'b1000

    // Output logic: out is 1 only when in state D
    assign out = state[3]; // D is 4'b1000, so state[3] is 1 when in state D

    // State transition logic
    // next_state is determined based on current state and input 'in'

    // For each state, determine next_state for in=0 and in=1
    // Use one-hot encoding for next_state

    // State A (state[0] is 1)
    // in=0: next_state = A (0001)
    // in=1: next_state = B (0010)
    // So: next_state = (state[0] & (~in)) ? 4'b0001 : (state[0] & in) ? 4'b0010 : 4'b0000

    // State B (state[1] is 1)
    // in=0: next_state = C (0100)
    // in=1: next_state = B (0010)
    // So: next_state = (state[1] & (~in)) ? 4'b0100 : (state[1] & in) ? 4'b0010 : 4'b0000

    // State C (state[2] is 1)
    // in=0: next_state = A (0001)
    // in=1: next_state = D (1000)
    // So: next_state = (state[2] & (~in)) ? 4'b0001 : (state[2] & in) ? 4'b1000 : 4'b0000

    // State D (state[3] is 1)
    // in=0: next_state = C (0100)
    // in=1: next_state = B (0010)
    // So: next_state = (state[3] & (~in)) ? 4'b0100 : (state[3] & in) ? 4'b0010 : 4'b0000

    // Combine all cases
    assign next_state = 
        (state[0] & (~in)) ? 4'b0001 :
        (state[0] & in) ? 4'b0010 :
        (state[1] & (~in)) ? 4'b0100 :
        (state[1] & in) ? 4'b0010 :
        (state[2] & (~in)) ? 4'b0001 :
        (state[2] & in) ? 4'b1000 :
        (state[3] & (~in)) ? 4'b0100 :
        (state[3] & in) ? 4'b0010 : 4'b0000;

endmodule

