module TopModule (
    input  a,
    input  b,
    input  c,
    input  d,
    output out_sop,
    output out_pos
);

    // Correct SOP expression for out_sop
    // out_sop is 1 for input values 2, 7, 15
    // Binary representations:
    // 2: 0010 -> !a & b & !c & d
    // 7: 0111 -> !a & b & c & d
    // 15: 1111 -> a & b & c & d
    assign out_sop = (!a & b & !c & d) | (!a & b & c & d) | (a & b & c & d);

    // Correct POS expression for out_pos
    // out_pos is 0 for input values 0, 1, 4, 5, 6, 9, 10, 13, 14
    // Binary representations:
    // 0: 0000 -> (a + !b + !c + !d)
    // 1: 0001 -> (a + !b + !c + d)
    // 4: 0100 -> (a + !b + c + !d)
    // 5: 0101 -> (a + !b + c + d)
    // 6: 0110 -> (a + b + !c + !d)
    // 9: 1001 -> (!a + !b + !c + d)
    // 10: 1010 -> (!a + !b + c + !d)
    // 13: 1101 -> (!a + b + !c + d)
    // 14: 1110 -> (!a + b + c + !d)
    assign out_pos = (a | (!b | !c | !d)) &
                     (a | (!b | !c | d)) &
                     (a | (!b | c | !d)) &
