    input  load,
    input  [255:0] data,
    output [255:0] q
);

    reg [255:0] next_q;
    reg [255:0] current_q;

    always @(posedge clk) begin
        if (load) begin
            current_q <= data;
        end else begin
            current_q <= next_q;
        end
    end

    always @(*) begin
        next_q = 256'h0;

        for (integer i = 0; i < 16; i = i + 1) begin
            for (integer j = 0; j < 16; j = j + 1) begin
                integer di, dj;
                integer count = 0;

                for (di = -1; di <= 1; di = di + 1) begin
                    for (dj = -1; dj <= 1; dj = dj + 1) begin
                        if (di == 0 && dj == 0) continue;
                        integer ni = (i + di) % 16;
                        integer nj = (j + dj) % 16;
                        if (current_q[ni * 16 + nj]) count = count + 1;
                    end
                end

                if (count == 0 || count == 1) begin
                    next_q[i * 16 + j] = 1'b0;
                end else if (count == 2) begin
                    next_q[i * 16 + j] = current_q[i * 16 + j];
                end else if (count == 3) begin
                    next_q[i * 16 + j] = 1'b1;
                end else begin
                    next_q[i * 16 + j] = 1'b0;
                end
            end
        end
    end

    assign q = current_q;

