                end else begin
                    next_state = WALK_LEFT;
                    walk_left = 1'b1;
                end
            end
        endcase

        // Handle direction changes due to bumps
        if (current_state != FALLING && current_state != DIGGING) begin
            if (bump_left) begin
                if (current_state == WALK_LEFT) begin
                    next_state = WALK_RIGHT;
                    walk_right = 1'b1;
                end else begin
                    next_state = WALK_RIGHT;
                    walk_right = 1'b1;
                end
            end else if (bump_right) begin
                if (current_state == WALK_RIGHT) begin
                    next_state = WALK_LEFT;
                    walk_left = 1'b1;
                end else begin
                    next_state = WALK_LEFT;
                    walk_left = 1'b1;
                end
            end
        end
    end

endmodule

module TopModule (
    input  clk,
    input  reset,
    input  [2:0] s,
    output reg fr2,
    output reg fr1,
    output reg fr0,
    output reg dfr
);

    // State machine states
    typedef enum reg [2:0] {
        STATE_LOW,     // Below s[0]
        STATE_MID1,    // Between s[1] and s[0]
        STATE_MID2,    // Between s[2] and s[1]
        STATE_HIGH     // Above s[2]
    } state_t;

    state_t current_state, next_state;

    // Reset state: all outputs high (flow max)
    always @(posedge clk or posedge reset) begin
        if (reset) begin
            current_state <= STATE_LOW;
            fr2 <= 1'b1;
            fr1 <= 1'b1;
            fr0 <= 1'b1;
            dfr <= 1'b1;
        end else begin
            current_state <= next_state;
        end
    end

    // Determine next state and outputs
    always @(current_state, s) begin
        next_state = current_state;
        fr2 = 1'b0;
        fr1 = 1'b0;
        fr0 = 1'b0;
        dfr = 1'b0;

        // Check sensor conditions
        if (s[2]) begin
            // Above s[2]
            next_state = STATE_HIGH;
            fr2 = 1'b0;
            fr1 = 1'b0;
            fr0 = 1'b0;
            dfr = 1'b0;
        end else if (s[1]) begin
            // Between s[2] and s[1]
            next_state = STATE_MID2;
            fr2 = 1'b0;
            fr1 = 1'b0;
            fr0 = 1'b0;
            dfr = 1'b0;
        end else if (s[0]) begin
            // Between s[1] and s[0]
            next_state = STATE_MID1;
            fr2 = 1'b0;
            fr1 = 1'b1;
            fr0 = 1'b1;
            dfr = 1'b0;
        end else begin
            // Below s[0]
            next_state = STATE_LOW;
            fr2 = 1'b1;
            fr1 = 1'b1;
            fr0 = 1'b1;
            dfr = 1'b1;
        end
    end

    // Determine dfr based on previous state and current state
    always @(current_state, next_state) begin
        if (current_state == STATE_LOW && next_state == STATE_MID1) begin
            dfr = 1'b1;
        end else if (current_state == STATE_MID1 && next_state == STATE_MID2) begin
            dfr = 1'b1;
        end else if (current_state == STATE_MID2 && next_state == STATE_HIGH) begin
            dfr = 1'b1;
        end else if (current_state == STATE_HIGH && next_state == STATE_MID2) begin
            dfr = 1'b1;
        end else if (current_state == STATE_MID2 && next_state == STATE_MID1) begin
            dfr = 1'b1;
        end else if (current_state == STATE_MID1 && next_state == STATE_LOW) begin
            dfr = 1'b1;
        end else if (current_state == STATE_LOW && next_state == STATE_MID2) begin
            dfr = 1'b1;
        end else if (current_state == STATE_MID1 && next_state == STATE_HIGH) begin
            dfr = 1'b1;
        end else if (current_state == STATE_MID2 && next_state == STATE_LOW) begin
            dfr = 1'b1;
        end else begin
            dfr = 1'b0;
        end
    end

endmodule

module TopModule (
    input  clk,
    input  areset,
    input  bump_left,
    input  bump_right,
    input  ground,
    input  dig,
    output reg walk_left,
    output reg walk_right,
    output reg aaah,
    output reg digging
);

    // Define states
    typedef enum reg [2:0] {
        WALK_LEFT,
        WALK_RIGHT,
        FALLING,
        DIGGING
    } state_t;

    state_t current_state, next_state;

    // State transition logic
    always @(posedge clk or posedge areset) begin
        if (areset) begin
            current_state <= WALK_LEFT;
            walk_left <= 1'b1;
            walk_right <= 1'b0;
            aaah <= 1'b0;
            digging <= 1'b0;
        end else begin
            current_state <= next_state;
        end
    end

    // Next state and output logic
    always @(*) begin
        next_state = current_state;
        walk_left = 1'b0;
        walk_right = 1'b0;
        aaah = 1'b0;
        digging = 1'b0;

        case (current_state)
            WALK_LEFT: begin
                if (!ground) begin
                    next_state = FALLING;
                    aaah = 1'b1;
                end else if (dig) begin
                    next_state = DIGGING;
                    digging = 1'b1;
                end else begin
                    next_state = WALK_LEFT;
                    walk_left = 1'b1;
                end
            end

            WALK_RIGHT: begin
                if (!ground) begin
                    next_state = FALLING;
                    aaah = 1'b1;
                end else if (dig) begin
                    next_state = DIGGING;
                    digging = 1'b1;
                end else begin
                    next_state = WALK_RIGHT;
                    walk_right = 1'b1;
                end
            end

            FALLING: begin
                if (ground) begin
                    next_state = WALK_LEFT;
                    walk_left = 1'b1;
                end else begin
                    next_state = FALLING;
                    aaah = 1'b1;
                end
            end

            DIGGING: begin
                if (!ground) begin
                    next_state = FALLING;
                    aaah = 1'b1;
                end else begin
                    next_state = WALK_LEFT;
                    walk_left = 1'b1;
                end
            end
        endcase

        // Handle direction changes due to bumps
        if (current_state != FALLING && current_state != DIGGING) begin
            if (bump_left) begin
                next_state = WALK_RIGHT;
                walk_right = 1'b1;
            end else if (bump_right) begin
                next_state = WALK_LEFT;
                walk_left = 1'b1;
            end
        end
    end

endmodule

